func main() {
	// Get user input
	angle := 0.0
	fmt.Println("Enter an angle between 0 and 2π:")
	fmt.Scan(&angle)

	// Check geometric sequence
	var sequence []float64
	ratio := (math.Cos(angle) - 1) / (math.Tan(angle) - math.Sin(angle))
	term := sequence = append(sequence, ratio)
	for i := 0; i < len(sequence); i++ {
		fmt.Printf("%f %f %f\n", ratio, term, angle)
		ratio = sequence[i+1]
		if ratio == angle {
			fmt.Println("Geometric sequence found!")
			return
		}
	}
	fmt.Println("Geometric sequence not found.")
}
